   268	static void road_label_layout_text(uint8_t kind, uint8_t road_vertical,
   269	    const char * name, char * out, size_t cap)
   270	{
   271	    size_t w = 0;
   272	    const char * p;
   273	
   274	    if (!out || cap == 0 || !name) {
   275	        return;
   276	    }
   277	
   278	    if (kind != VMAP_LABEL_ROAD || !road_vertical) {
   279	        lv_strlcpy(out, name, cap);
   280	        return;
   281	    }
   282	
   283	    p = name;
   284	    while (*p != '\0') {
   285	        uint32_t n = utf8_char_bytes(p);
   286	        if (n == 0) {
   287	            break;
   288	        }
   289	        if (w > 0) {
   290	            if (w + 1 >= cap) {
   291	                break;
   292	            }
   293	            out[w++] = '\n';
   294	        }
   295	        if (w + n >= cap) {
   296	            break;
   297	        }
   298	        lv_memcpy(out + w, p, n);
   299	        w += n;
   300	        p += n;
   301	    }
   302	    out[w] = '\0';
