   460	static int32_t road_name_near_index(const vmap_label_collector_t * col,
   461	    const char * name, uint8_t len, int32_t x, int32_t y)
   462	{
   463	    int32_t i;
   464	    int32_t lim;
   465	    int32_t lim2;
   466	    double spacing_x;
   467	    double spacing_y;
   468	
   469	    if (!col || !name || len == 0) {
   470	        return -1;
   471	    }
   472	
   473	    /*
   474	     * Keep repeats dense enough that a viewport crossing a long road sees a
   475	     * name, while still merging the duplicate anchors emitted by two tiles at
   476	     * their seam.
   477	     */
   478	    road_label_spacing_from_viewport(col->view_w, col->view_h,
   479	        &spacing_x, &spacing_y);
   480	    lim = (int32_t)lround((spacing_x + spacing_y) * 0.5);
   481	    if (lim < 60) {
   482	        lim = 60;
   483	    }
   484	    lim2 = lim * lim;
   485	
   486	    for (i = 0; i < col->count; i++) {
   487	        int32_t dx;
   488	        int32_t dy;
   489	
   490	        if (col->items[i].kind != VMAP_LABEL_ROAD) {
   491	            continue;
   492	        }
   493	        if (strncmp(col->items[i].name, name, (size_t)len) != 0
   494	            || col->items[i].name[len] != '\0') {
   495	            continue;
   496	        }
   497	
   498	        dx = col->items[i].x - x;
   499	        dy = col->items[i].y - y;
   500	        if (dx * dx + dy * dy < lim2) {
   501	            return i;
   502	        }
   503	    }
   504	    return -1;
   505	}
