   854	    const int32_t tile_size = 256;
   855	    double half_w = (canvas_w / 2.0) / scale;
   856	    double half_h = (canvas_h / 2.0) / scale;
   857	    double pad = (double)ring * tile_size;
   858	    double left = (double)center_x - half_w - pad;
   859	    double top = (double)center_y - half_h - pad;
   860	    double right = (double)center_x + half_w + pad;
   861	    double bottom = (double)center_y + half_h + pad;
   862	
   863	    *tx_min = (int32_t)(left / tile_size) - (left < 0 ? 1 : 0);
   864	    *ty_min = (int32_t)(top / tile_size) - (top < 0 ? 1 : 0);
   865	    *tx_max = (int32_t)(right / tile_size);
   866	    *ty_max = (int32_t)(bottom / tile_size);
   867	}
