   962	/** @brief 旋转标签优先级：层级 → prio 大 → 离屏幕中心近。 */
   963	static bool vmap_rot_pick_better(const vmap_rot_pick_t * a,
   964	    const vmap_rot_pick_t * b)
   965	{
   966	    if (a->tier != b->tier) {
   967	        return a->tier < b->tier;
   968	    }
   969	    if (a->prio != b->prio) {
   970	        return a->prio > b->prio;
   971	    }
   972	    return a->dist2 < b->dist2;
   973	}
   974	
   975	static bool vmap_rot_boxes_overlap(const lv_area_t * a, const lv_area_t * b,
   976	    int32_t gap)
   977	{
   978	    return a->x1 - gap <= b->x2 && a->x2 + gap >= b->x1
   979	        && a->y1 - gap <= b->y2 && a->y2 + gap >= b->y1;
   980	}
