   982	/**
   983	 * @brief 把本帧收集到的路名按"旋转后的屏幕位置"摆成正立文本对象。
   984	 * @details 文本不烘进画布（否则会跟着地图转成斜字）；位置 = R 中心 +
   985	 *          R(θ)·(画布点 - 骑手点)，再换算到 map_area 坐标。同名只留一条；
   986	 *          按层级/prio/离中心近排序后逐个放置，整框出视口或与已放标签
   987	 *          重叠的直接跳过，避免两个路名叠在一起。
   988	 */
   989	static void vmap_rot_labels_update(vmap_view_t * view, int32_t pivot_x,
   990	    int32_t pivot_y)
   991	{
   992	    const double th = (double)view->rot10 * 0.1 * M_PI / 180.0;
   993	    const double c = cos(th);
   994	    const double s = sin(th);
   995	    const int32_t cx = view->view_w / 2;
   996	    const int32_t cy = view->view_h / 2;
   997	    vmap_rot_pick_t pick[VMAP_ROT_PICK_MAX];
   998	    lv_area_t placed[VMAP_ROT_LABEL_MAX];
   999	    const char * taken[VMAP_ROT_LABEL_MAX];
  1000	    int32_t pick_n = 0;
  1001	    int32_t placed_n = 0;
  1002	    int32_t i;
  1003	    int32_t n = 0;
  1004	
  1005	    if (!view->rot_labels || view->font == NULL || view->label_col.count <= 0) {
  1006	        for (i = 0; i < VMAP_ROT_LABEL_MAX; i++) {
  1007	            lv_obj_add_flag(view->rot_label[i], LV_OBJ_FLAG_HIDDEN);
  1008	        }
  1009	        view->rot_label_n = 0;
  1010	        return;
  1011	    }
  1012	
  1013	    /* 1) 先算屏幕位置，按优先级挑出前 N 个候选（只排序，不做碰撞）。 */
  1014	    for (i = 0; i < view->label_col.count; i++) {
  1015	        const vmap_label_cand_t * it = &view->label_col.items[i];
  1016	        const double dx = (double)it->x - (double)pivot_x;
  1017	        const double dy = (double)it->y - (double)pivot_y;
  1018	        const int32_t sx = (int32_t)lround((double)view->rw / 2.0
  1019	            + (c * dx - s * dy)) - view->r_margin;
  1020	        const int32_t sy = (int32_t)lround((double)view->rh / 2.0
  1021	            + (s * dx + c * dy)) - view->r_margin;
  1022	        const int32_t sy_vis = sy + view->y_bias;
  1023	        const int32_t ddx = sx - cx;
  1024	        const int32_t ddy = sy_vis - cy;
  1025	        vmap_rot_pick_t e;
  1026	        int32_t pos;
  1027	
  1028	        if (it->name[0] == '\0') {
  1029	            continue;
  1030	        }
  1031	        /* 中心离视口太远的先排除；真正裁剪在放置阶段按整框做。 */
  1032	        if (sx < -48 || sy_vis < -48 || sx > view->view_w + 48
  1033	            || sy_vis > view->view_h + 48) {
  1034	            continue;
  1035	        }
  1036	
  1037	        e.idx = (int16_t)i;
  1038	        e.tier = vmap_rot_label_tier(it->kind);
  1039	        e.prio = it->prio;
  1040	        e.dist2 = ddx * ddx + ddy * ddy;
  1041	        e.sx = sx;
  1042	        e.sy = sy;
  1043	
  1044	        /* 插入排序：pick[0] 最优，容量 VMAP_ROT_PICK_MAX。 */
  1045	        pos = pick_n;
  1046	        while (pos > 0 && vmap_rot_pick_better(&e, &pick[pos - 1])) {
  1047	            if (pos < VMAP_ROT_PICK_MAX) {
  1048	                pick[pos] = pick[pos - 1];
  1049	            }
  1050	            pos--;
  1051	        }
  1052	        if (pos < VMAP_ROT_PICK_MAX) {
  1053	            pick[pos] = e;
  1054	            if (pick_n < VMAP_ROT_PICK_MAX) {
  1055	                pick_n++;
  1056	            }
  1057	        }
  1058	    }
  1059	
  1060	    /* 2) 按优先级放置：整框必须在视口内，且不得与已放标签重叠。 */
  1061	    for (i = 0; i < pick_n && n < VMAP_ROT_LABEL_MAX; i++) {
  1062	        const vmap_label_cand_t * it = &view->label_col.items[pick[i].idx];
  1063	        lv_obj_t * l = view->rot_label[n];
  1064	        lv_area_t box;
  1065	        lv_coord_t w;
  1066	        lv_coord_t h;
  1067	        int32_t k;
  1068	        bool dup = false;
  1069	
  1070	        for (k = 0; k < n; k++) {
  1071	            if (strcmp(taken[k], it->name) == 0) {
  1072	                dup = true;
  1073	                break;
  1074	            }
  1075	        }
  1076	        if (dup) {
  1077	            continue;
  1078	        }
  1079	
  1080	        lv_label_set_text(l, it->name);
  1081	        lv_obj_set_style_text_color(l,
  1082	            lv_color_hex(vmap_rot_label_color(it->kind)), 0);
  1083	        /* 字号与正北烘进底图的标准一致：地名 16，路名/水名/POI 12。 */
  1084	        lv_obj_set_style_text_font(l, vmap_rot_label_font(view, it->kind), 0);
  1085	        lv_obj_update_layout(l);
  1086	        w = lv_obj_get_width(l);
  1087	        h = lv_obj_get_height(l);
  1088	
  1089	        box.x1 = pick[i].sx - w / 2;
  1090	        box.y1 = pick[i].sy + view->y_bias - h / 2;
  1091	        box.x2 = box.x1 + w - 1;
  1092	        box.y2 = box.y1 + h - 1;
  1093	        if (box.x1 < 0 || box.y1 < 0
  1094	            || box.x2 >= view->view_w || box.y2 >= view->view_h) {
  1095	            continue;
  1096	        }
  1097	        for (k = 0; k < placed_n; k++) {
  1098	            if (vmap_rot_boxes_overlap(&box, &placed[k],
  1099	                    VMAP_ROT_LABEL_GAP)) {
  1100	                break;
  1101	            }
  1102	        }
  1103	        if (k < placed_n) {
  1104	            continue;
  1105	        }
  1106	
  1107	        placed[placed_n++] = box;
  1108	        view->rlx[n] = box.x1;
  1109	        view->rly[n] = box.y1 - view->y_bias;
  1110	        lv_obj_set_pos(l, view->rlx[n],
  1111	            (lv_coord_t)(view->rly[n] + view->y_bias));
  1112	        lv_obj_clear_flag(l, LV_OBJ_FLAG_HIDDEN);
  1113	        taken[n] = it->name;
  1114	        n++;
  1115	    }
  1116	
  1117	    for (i = n; i < VMAP_ROT_LABEL_MAX; i++) {
  1118	        lv_obj_add_flag(view->rot_label[i], LV_OBJ_FLAG_HIDDEN);
  1119	    }
  1120	    view->rot_label_n = (uint8_t)n;
  1121	}
