  1131	/**
  1132	 * @brief 用 EPIC 把整幅画布按当前 rot10 重新烘进 R。
  1133	 *
  1134	 * @details 一次约 138 ms（R 288×264，EPIC 任意角 ~0.55 Mpx/s），所以只在**角度变了 /
  1135	 *          余量用完 / 整帧结束**时调用；平地跟车只移动 R 的对象。
  1136	 */
  1137	static bool vmap_rot_full(vmap_view_t * view)
  1138	{
  1139	    int32_t pivot_x;
  1140	    int32_t pivot_y;
  1141	
  1142	    if (view == NULL || !view->heading_up || view->rbuf == NULL
  1143	        || view->cbuf == NULL || view->rcanvas == NULL) {
  1144	        return false;
  1145	    }
  1146	
  1147	    /* 切换窗口里 C 还在重铺：此时烘 R 会把半成品/旧标签带上屏。 */
  1148	    if (view->heading_switch_pending) {
  1149	        return false;
  1150	    }
  1151	
  1152	    /*
  1153	     * ⚠ 帧在飞时**绝不能烘**：`vmap_rot_full` 会被 GNSS 定时器经
  1154	     * `apply_canvas_pos → vmap_rot_track` 调到，而那时正北画布只画了一半瓦片、
  1155	     * 标签收集器也只填了一部分 ⇒ 烘出来是"半成品"，下一帧再纠正，观感就是
  1156	     * 地图卡住 + 文字乱跳（2026-10-28 现场）。等 `render_finish` 里再烘。
  1157	     */
  1158	    if (view->pump_phase != 0u) {
  1159	        return false;
  1160	    }
  1161	
  1162	    /*
  1163	     * 失败后的重试限频放在**这里**，而不是只放在 service 里：跟车余量、开关切换、
  1164	     * 帧末都直接调本函数，否则一次失败会在同一拍里被下一个入口再次触发。
  1165	     * 只限"失败重试"，正常重烘（帧末/余量/角度）不受这条窗口影响。
  1166	     */
  1167	    if (view->rot_fail_valid
  1168	        && (uint32_t)(lv_tick_get() - view->last_fail_ms) < VMAP_ROT_BAKE_MIN_MS) {
  1169	        return false;
  1170	    }
  1171	
  1172	    /* 骑手在画布里的位置 = 画布中心 + 跟车 pan。 */
  1173	    pivot_x = view->margin + view->view_w / 2 + (int32_t)lround(view->pan_dx);
  1174	    pivot_y = view->margin + view->view_h / 2 + (int32_t)lround(view->pan_dy);
  1175	    if (pivot_x < 0 || pivot_y < 0 || pivot_x >= view->w || pivot_y >= view->h) {
  1176	        pivot_x = view->w / 2;
  1177	        pivot_y = view->h / 2;
  1178	    }
  1179	
  1180	    if (!myvendor_epic_rotate(view->cbuf, view->stride, view->w, view->h,
  1181	            view->rbuf, view->rstride, view->rw, view->rh, view->rot10,
  1182	            pivot_x, pivot_y, view->rw / 2, view->rh / 2)) {
  1183	        /*
  1184	         * 失败分两种：参数/硬件不可用（R 没动），或 **EPIC 超时**（R 可能已被写了
  1185	         * 一部分，上一帧不能再信）。两种情况都按"R 是脏的"处理 —— 这里的记账是
  1186	         * 全树唯一的收口点，调用方（service / 跟车 / 帧末 / 开关切换）都不必各自判断：
  1187	         *   ① `rot_pending`：service 每拍重试整幅，直到成功；
  1188	         *   ② `last_fail_ms`：失败重试限频（入口处），避免同一拍被别的入口再打一次。
  1189	         *
  1190	         * ⚠ 已知边界：R 是单缓冲、EPIC 直写，超时后**无法回滚**上一帧。
  1191	         *   失败到下一次成功重烘之间，屏上可能是新旧混合的一帧；这段时间里
  1192	         *   `rot_broken` 会**冻结跟车平移**（否则按旧 r_pan 继续挪会把新旧两种基准
  1193	         *   叠在一起，错位越滚越大）。重试间隔 ≥1200 ms，连续失败可更久。
  1194	         *   要彻底消除得双缓冲（多 152 KB PSRAM），未做。
  1195	         */
  1196	        view->rot_pending = true;
  1197	        view->rot_fail_valid = true;
  1198	        view->rot_broken = true;
  1199	        view->last_fail_ms = lv_tick_get();
  1200	        return false;
  1201	    }
  1202	
  1203	    view->r_pan_x = view->pan_dx;
  1204	    view->r_pan_y = view->pan_dy;
  1205	    view->r_rot10 = view->rot10;
  1206	    view->rot_pending = false;
  1207	    view->rot_fail_valid = false;
  1208	    view->rot_broken = false;
  1209	    /* 余量重烘/帧末重烘/增量重烘都计入同一个限频窗口。 */
  1210	    view->last_bake_ms = lv_tick_get();
  1211	    vmap_rot_place(view, 0, 0);
  1212	    vmap_rot_labels_update(view, pivot_x, pivot_y);
  1213	    lv_obj_invalidate(view->rcanvas);
  1214	    return true;
  1215	}
