  1254	            lv_obj_clear_flag(view->rcanvas, LV_OBJ_FLAG_HIDDEN);
  1255	        }
  1256	        if (view->canvas) {
  1257	            lv_obj_invalidate(view->canvas);
  1258	        }
  1259	        return;
  1260	    }
  1261	
  1262	    angle = (view->want_rot10 != view->rot10);
  1263	    if (!angle && !view->rot_pending) {
  1264	        return;
  1265	    }
  1266	    if (view->pump_phase != 0u || view->rcanvas == NULL
  1267	        || view->render_rev == 0u
  1268	        || lv_obj_has_flag(view->rcanvas, LV_OBJ_FLAG_HIDDEN)) {
  1269	        return;                 /* 帧在飞（帧末会烘）或还没显示/还没有首帧 */
  1270	    }
  1271	    if (view->last_bake_ms != 0u
  1272	        && lv_tick_elaps(view->last_bake_ms) < VMAP_ROT_BAKE_MIN_MS) {
  1273	        return;                 /* 限频窗口未到：下一拍再来 */
  1274	    }
  1275	    /*
  1276	     * 待应用角度与"帧外增量"合并到**同一次**重烘：否则先用旧角度烘一次增量会刷新
  1277	     * `last_bake_ms`，把角度请求一直挡在窗口外（持续记录时地图永远保持旧朝向）。
  1278	     * 角度**成功烘完才提交**：EPIC 旋转失败时保留 want_rot10，下一拍自动重试，
  1279	     * 不会把请求悄悄丢掉（否则静止时再没有别的东西会触发重烘）。
  1280	     */
  1281	    {
  1282	        const int32_t prev_rot10 = view->rot10;
  1283	
  1284	        /* 探针放在限频检查**之后**：这里才是真的要烘一次（之前的位置会把被窗口挡掉
  1285	         * 的重试也记成一次触发）。 */
  1286	        vmap_rot_why(angle ? 'A' : 'N');
  1287	        view->rot10 = view->want_rot10;
  1288	        if (!vmap_rot_full(view)) {
  1289	            /* 失败记账在 `vmap_rot_full()` 里统一做（见那里的注释）。 */
  1290	            view->rot10 = prev_rot10;
  1291	        }
  1292	    }
