  1295	/**
  1296	 * @brief 跟车：R 里的内容该位移 (-R(θ)·Δpan)；余量够只挪对象，不够重烘。
  1297	 */
  1298	static void vmap_rot_track(vmap_view_t * view)
  1299	{
  1300	    const double th = (double)view->r_rot10 * 0.1 * M_PI / 180.0;
  1301	    const double c = cos(th);
  1302	    const double s = sin(th);
  1303	    const double dpx = view->pan_dx - view->r_pan_x;
  1304	    const double dpy = view->pan_dy - view->r_pan_y;
  1305	    const int32_t sx = (int32_t)lround(-(c * dpx - s * dpy));
  1306	    const int32_t sy = (int32_t)lround(-(s * dpx + c * dpy));
  1307	    const int32_t lim = view->r_margin - VMAP_ROT_TRACK_GUARD;
  1308	
  1309	    /*
  1310	     * R 可能被写坏（上次整幅超时）：冻结平移，等一次成功重烘把 R 整体重写。
  1311	     * 否则这次位移是按"上一次成功的 r_pan"算的，而 R 里已有一段按新 pan 写入的像素。
  1312	     */
  1313	    if (view->rot_broken) {
  1314	        return;
  1315	    }
  1316	
  1317	    if (view->rot10 != view->r_rot10
  1318	        || abs((int)sx) > lim || abs((int)sy) > lim) {
  1319	        vmap_rot_why('T');
  1320	        vmap_rot_full(view);    /* 角度变了、或余量用完了；失败记账在它内部 */
  1321	        return;
  1322	    }
  1323	
  1324	    vmap_rot_place(view, sx, sy);
  1325	}
  1326	
  1327	static void vmap_view_apply_canvas_pos(vmap_view_t * view, double dx, double dy)
  1328	{
  1329	    lv_coord_t px;
  1330	    lv_coord_t py;
  1331	
  1332	    if (!view || !view->canvas) {
  1333	        return;
  1334	    }
  1335	
  1336	    /* 请求量原样记账（浮点），只有上屏这一步取整 —— 亚像素余量的唯一去处。 */
  1337	    view->pan_rx = dx;
  1338	    view->pan_ry = dy;
  1339	    px = (lv_coord_t)lround(dx);
  1340	    py = (lv_coord_t)lround(dy);
  1341	
  1342	    if (px == view->last_pan_px && py == view->last_pan_py) {
  1343	        return;
  1344	    }
  1345	
  1346	    /*
  1347	     * Moving a canvas invalidates the complete visible map. Coalesce sub-pixel
  1348	     * GNSS movement; the centered arrow still updates normally.
  1349	     */
  1350	    if (view->last_pan_px != INT32_MIN && view->last_pan_py != INT32_MIN
  1351	        && abs((int)px - view->last_pan_px) < VMAP_PAN_MIN_STEP_PX
  1352	        && abs((int)py - view->last_pan_py) < VMAP_PAN_MIN_STEP_PX) {
  1353	        return;
  1354	    }
  1355	
  1356	    view->pan_dx = (double)px;
  1357	    view->pan_dy = (double)py;
  1358	    view->last_pan_px = px;
  1359	    view->last_pan_py = py;
  1360	    view->map_rev++;
  1361	    vmap_label_collector_set_focus(&view->label_col,
  1362	        view->w / 2 + px, view->h / 2 + py);
  1363	#if defined(CONFIG_MYVENDOR_BICYCLE_INVAL_PROBE) && CONFIG_MYVENDOR_BICYCLE_INVAL_PROBE
  1364	    bicycle_inval_probe_tag("vmap_pan");
  1365	#endif
  1366	    /* lv_obj_set_pos already invalidates old + new areas; do not inval again. */
  1367	    /* y_bias 只加在屏幕位置上：pan_dy 与投影原点都不动，于是偏置与跟车/rebase
  1368	     * 的数学完全解耦（偏置变化既不触发重算，也不改变 rebase 时机）。 */
  1369	    if (!view->heading_up || view->heading_switch_pending
  1370	        || !lv_obj_has_flag(view->canvas, LV_OBJ_FLAG_HIDDEN)) {
  1371	        lv_obj_set_pos(view->canvas,
  1372	            (lv_coord_t)(-view->margin - px),
  1373	            (lv_coord_t)(-view->margin - py + view->y_bias));
  1374	        return;
  1375	    }
  1376	
  1377	    /*
  1378	     * 航向朝上：不再让 LVGL 旋转画布（那样每次平移都要重跑一次任意角 transform，
  1379	     * 实测 60 ms/次）。改成维护一块**屏幕对齐的旋转缓冲 R**：只有角度变化或
  1380	     * 余量用完才重烘，平地跟车只移动 R 的对象（见 vmap_rot_track）。
  1381	     */
  1382	    vmap_rot_track(view);
  1383	}
