  1431	            if (view->rcanvas) {
  1432	                lv_obj_clear_flag(view->rcanvas, LV_OBJ_FLAG_HIDDEN);
  1433	            }
  1434	            if (view->canvas) {
  1435	                lv_obj_add_flag(view->canvas, LV_OBJ_FLAG_HIDDEN);
  1436	            }
  1437	        }
  1438	    } else {
  1439	        view->heading_switch_pending = 0;
  1440	        view->heading_switch_ready = 0;
  1441	        if (view->rcanvas) {
  1442	            lv_obj_add_flag(view->rcanvas, LV_OBJ_FLAG_HIDDEN);
  1443	        }
  1444	        if (view->canvas) {
  1445	            lv_obj_clear_flag(view->canvas, LV_OBJ_FLAG_HIDDEN);
  1446	        }
  1447	        /* 正立路名只在航向朝上时用；退回正北后由烘焙路径接管。 */
  1448	        {
  1449	            int32_t i;
  1450	
  1451	            for (i = 0; i < VMAP_ROT_LABEL_MAX; i++) {
  1452	                if (view->rot_label[i] != NULL) {
  1453	                    lv_obj_add_flag(view->rot_label[i], LV_OBJ_FLAG_HIDDEN);
  1454	                }
  1455	            }
  1456	            view->rot_label_n = 0;
  1457	        }
  1458	    }
  1459	
  1460	    /* 位置公式与标签开关都变了：按新公式重摆，再整幅重来一帧。 */
  1461	    view->last_pan_px = INT32_MIN;
  1462	    view->last_pan_py = INT32_MIN;
  1463	    vmap_view_apply_canvas_pos(view, view->pan_dx, view->pan_dy);
  1464	    syslog(LOG_NOTICE, "[map] heading-up %s\n", enable ? "on" : "off");
  1465	
  1466	    /* 首帧之前不要提前开帧（开机还没进过地图时由页面层控制）。 */
  1467	    if (!enable && view->render_rev != 0u) {
  1468	        vmap_view_render(view);
  1469	    }
  1470	}
